/**
 * Performs a right node rotation.
 * @param node a node to rotate
 * @return a new parent of the {@code node}
 */
private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        throw new IllegalArgumentException("Rotation requires a non-null node");
    }
    if (node.right == null) {
        throw new IllegalArgumentException("Rotation requires a node with a non-null right child");
    }
    TreeNode<T> right = node.right;
    node.right = right.left;
    right.left = node;
    return right;
}

/**
 * Performs a right node rotation.
 * @param node a node to rotate
 * @return a new parent of the {@code node}
 */
private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null");
    }
    if (node.getRight() == null) {
        throw new IllegalStateException("Node does not have a right child");
    }
    TreeNode<T> newParent = node.getRight();
    node.setRight(newParent.getLeft());
    newParent.setLeft(node);
    return newParent;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        throw new IllegalArgumentException("Cannot rotate a null node");
    }

    TreeNode<T> newParent = node.getRightChild();

    if (newParent == null) {
        throw new IllegalStateException("Cannot rotate a node without a right child");
    }

    node.setRightChild(newParent.getRightChild());
    newParent.setRightChild(node);

    return newParent;
}

/** 
 * Performs a right node rotation.
 * @param node a node to rotate
 * @return a new parent of the {@code node}
 */
private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null");
    }

    TreeNode<T> newParent = node.left;
    node.left = newParent.right;
    newParent.right = node;

    return newParent;
}

