public static void addToClassPath(Vector<URL> cpV, String dir) {
    // Step 1: Validate input
    if (cpV == null || dir == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }
    if (!dir.endsWith(File.separator)) {
        throw new IllegalArgumentException("Directory path must end with a separator");
    }

    // Step 2: Iterate over the files in the directory
    File[] files = new File(dir).listFiles();
    if (files == null) {
        throw new IllegalArgumentException("Directory does not exist");
    }

    // Step 3: Add each JAR file to the classpath vector
    for (File file : files) {
        if (file.isFile() && file.getName().toLowerCase().endsWith(".jar")) {
            try {
                URL url = file.toURI().toURL();
                cpV.add(url);
            } catch (MalformedURLException e) {
                throw new IllegalArgumentException("JAR file URL is invalid", e);
            }
        }
    }
}

/**
 * Add all the jar files in a directory to the classpath, represented as a Vector of URLs.
 */
@SuppressWarnings("unchecked")
public static void addToClassPath(Vector<URL> cpV, String dir) {
    if (dir == null || dir.isEmpty()) {
        throw new IllegalArgumentException("Invalid directory path provided");
    }

    File dirFile = new File(dir);
    if (!dirFile.isDirectory()) {
        throw new IllegalArgumentException("Path provided is not a directory");
    }

    String[] files = dirFile.list();
    for (String file : files) {
        if (file.endsWith(".jar")) {
            try {
                cpV.add(new URL("file:" + file));
            } catch (MalformedURLException e) {
                throw new RuntimeException("Error creating URL for jar file", e);
            }
        }
    }
}

