        format = format.substring(startIndex + 2);
    }
    return builder.toString();
}

public String format(LoggingEvent event) {
    // Initialize the conversion pattern to the default pattern
    String conversionPattern = "%m%n";

    // Get the format value from the logging event
    Format format = event.getFormat();

    // If the format value is not null, use it to generate the conversion pattern
    if (format != null) {
        conversionPattern = format.getPattern();
    }

    // Replace the format specifiers in the conversion pattern with the corresponding values from the logging event
    conversionPattern = conversionPattern.replace("%m", event.getMessage());
    conversionPattern = conversionPattern.replace("%n", System.lineSeparator());
    conversionPattern = conversionPattern.replace("%p", event.getLevel().name());
    conversionPattern = conversionPattern.replace("%d", event.getDate().toString());
    conversionPattern = conversionPattern.replace("%r", event.getThreadName());
    conversionPattern = conversionPattern.replace("%c", event.getLoggerName());

    // Return the formatted string
    return conversionPattern;
}

