public void write(byte b[]) throws IOException {
    // Step 1: Check if the input byte array is null or empty
    if (b == null || b.length == 0) {
        return;
    }

    // Step 2: Convert the byte array to a ByteBuffer
    ByteBuffer buffer = ByteBuffer.wrap(b);

    // Step 3: Write the ByteBuffer to the output stream
    while (buffer.hasRemaining()) {
        int bytesToWrite = Math.min(buffer.remaining(), this.writeBuffer.length - this.writeBufferPosition);
        buffer.get(this.writeBuffer, this.writeBufferPosition, bytesToWrite);
        this.writeBufferPosition += bytesToWrite;
    }
}

@Override
public void write(byte[] b) throws IOException {
    // Step 1: Check if the input array is null or empty
    if (b == null || b.length == 0) {
        throw new IllegalArgumentException("The input byte array is null or empty");
    }

    // Step 2: Calculate the number of bytes to write
    int bytesToWrite = b.length;

    // Step 3: Check if the output stream is closed
    if (this.closed) {
        throw new IOException("The output stream is closed");
    }

    // Step 4: Write the bytes to the output stream
    for (int i = 0; i < bytesToWrite; i++) {
        this.write(b[i]);
    }

    // Step 5: Flush the output stream
    this.flush();
}

