            V vertexValue = resultMap.get(vertex);
            if (!this.vertices.containsKey(vertex)) {
                this.vertices.put(vertex, vertexValue);
            }

            for (String neighbor : resultMap.keySet()) {
                if (!this.vertices.containsKey(neighbor)) {
                    this.vertices.put(neighbor, neighbor);
                }

                if (!this.edges.containsKey(vertex + "-" + neighbor)) {
                    this.edges.put(vertex + "-" + neighbor, new Edge(vertexValue, resultMap.get(neighbor)));
                }
            }
        }
    }

