    if (resultMap.isEmpty()) {
        throw new EmptyResultMapException("The result map is empty");
    }

    // Construct the bipartite graph
    Graph<V,E> bipartiteGraph = new Graph<>();

    Map<String,V> nodeMap = new HashMap<>();
    for (V vertex : target.getVertices()) {
        if (vertex.isBipartite()) {
            bipartiteGraph.addVertex(vertex);
            nodeMap.put(vertex, vertex);
        }
    }

    for (E edge : target.getEdges()) {
        if (edge.getDestination().isBipartite() && edge.getSource().isBipartite()) {
            bipartiteGraph.addEdge(edge.getSource(), edge.getDestination());
        }
    }

    resultMap.clear();
    for (V vertex : bipartiteGraph.getVertices()) {
        resultMap.put(vertex, vertex);
    }
}

