 * On Windows 2000, the directory is "lf5" under the Documents and Settings directory.
 * On other platforms, the directory is wherever the user.home variable points.
 * @return the path to the configuration directory
 */
private static String getConfigDirectoryPath() {
    // Get the user's home directory
    String userHome = System.getProperty("user.home");

    // Determine the operating system
    String osName = System.getProperty("os.name").toLowerCase();
    if (osName.contains("windows")) {
        // On Windows, the directory is "lf5" under the Documents and Settings directory
        return userHome + "\\Documents and Settings\\lf5";
    } else {
        // On other platforms, the directory is wherever the user.home variable points
        return userHome;
    }
}

