public long readLong(final int offset) {
  long value;
  try {
    value = ((long) readInt(offset)) << 32;
    value |= ((long) readInt(offset + 4)) & 0xFFFFFFFFL;
  } catch (IOException e) {
    throw new IllegalStateException("Error reading long value at offset " + offset, e);
  }
  return value;
}

