/**
 * Split time ranges to ensure the start time and end time is small then  {@link #FETCH_DATA_DURATION}
 */
protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = end - start;
    if (duration > FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("Start and end time difference is too large, please adjust.");
    }
    timeRanges.add(new TimeRange(start, end));
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    // Check that start and end times are valid
    if (start < 0 || end < 0 || start > end) {
        throw new IllegalArgumentException("Invalid time range: start time must be before end time");
    }

    // Split the time range into smaller ranges that are at most FETCH_DATA_DURATION long
    long rangeStart = start;
    long rangeEnd = start + FETCH_DATA_DURATION;
    List<TimeRange> timeRanges = new ArrayList<>();
    while (rangeStart < end) {
        timeRanges.add(new TimeRange(rangeStart, Math.min(rangeEnd, end)));
        rangeStart = rangeEnd;
        rangeEnd = rangeStart + FETCH_DATA_DURATION;
    }
    return timeRanges;
}

/** 
 * Split time ranges to insure the start time and end time is small then  {@link #FETCH_DATA_DURATION}
 */
protected List<TimeRange> buildTimeRanges(long start, long end)
{
  if (start < 0 || end < 0 || start >= end) {
    throw new IllegalArgumentException("Start and end times must be non-negative and start time must be before end time");
  }
  List<TimeRange> timeRanges = new ArrayList<>();
  while (start < end) {
    long fetchStart = start;
    start += FETCH_DATA_DURATION;
    long fetchEnd = start;
    timeRanges.add(new TimeRange(fetchStart, fetchEnd));
  }
  return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long fetchDataDuration = 1000 * 60 * 60 * 24; // 24 hours

    if (start > end) {
        throw new IllegalArgumentException("Start time cannot be after end time");
    }

    long currentStart = start;
    long currentEnd = Math.min(start + fetchDataDuration, end);
    while (currentStart < end) {
        timeRanges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
        currentEnd = Math.min(currentStart + fetchDataDuration, end);
    }

    return timeRanges;
}

