static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("Day step must be greater than 0.");
    }
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("Time bucket must be greater than 0.");
    }

    long reFormattedTimeBucket = timeBucket;

    // Calculate the start and end dates of the time bucket
    LocalDate startDate = LocalDate.ofEpochDay(timeBucket);
    LocalDate endDate = startDate.plusDays(dayStep - 1);

    // If the end date is before the start date, then the time bucket is invalid
    if (endDate.isBefore(startDate)) {
        throw new IllegalArgumentException("Invalid time bucket.");
    }

    // Calculate the new start date
    LocalDate newStartDate = startDate.withDayOfMonth(1);

    // If the new start date is after the end date, then the time bucket is invalid
    if (newStartDate.isAfter(endDate)) {
        throw new IllegalArgumentException("Invalid time bucket.");
    }

    // Calculate the new end date
    LocalDate newEndDate = newStartDate.plusDays(dayStep - 1);

    // If the new end date is before the new start date, then the time bucket is invalid
    if (newEndDate.isBefore(newStartDate)) {
        throw new IllegalArgumentException("Invalid time bucket.");
    }

    // Calculate the new time bucket
    reFormattedTimeBucket = newEndDate.toEpochDay();

    return reFormattedTimeBucket;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0 || dayStep > 31) {
        throw new IllegalArgumentException("Invalid dayStep value: " + dayStep + ". It should be between 1 and 31");
    }
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("Invalid timeBucket value: " + timeBucket + ". It should be a positive integer");
    }

    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);

    int startOfBucket = (int) (timeBucket - day + 1);

    int endOfBucket = startOfBucket + dayStep - 1;

    return (long) (year * 10000 + month * 100 + endOfBucket);
}

/**
 * Follow the dayStep to re-format the time bucket literal long value. Such as, in dayStep == 11, 20000105 re-formatted time bucket is 20000101, 20000115 re-formatted time bucket is 20000112, 20000123 re-formatted time bucket is 20000123
 */
static long compressTimeBucket(long timeBucket,int dayStep){
  // handling invalid input
  if(timeBucket < 0 || dayStep < 1) {
    throw new IllegalArgumentException("Invalid input: timeBucket or dayStep is less than 0");
  }

  // handling invalid dayStep
  if(dayStep == 0) {
    throw new IllegalArgumentException("Invalid input: dayStep should not be 0");
  }

  // calculating the offset
  long offset = (timeBucket - 1) % dayStep;

  // handling the special case when dayStep is 1
  if(dayStep == 1) {
    offset = 0;
  }

  // calculating the compressed time bucket
  long compressedTimeBucket = timeBucket - offset;

  return compressedTimeBucket;
}

/**
 * Follow the dayStep to re-format the time bucket literal long value. Such as, in dayStep == 11, 20000105 re-formatted time bucket is 20000101, 20000115 re-formatted time bucket is 20000112, 20000123 re-formatted time bucket is 20000123
 */
static long compressTimeBucket(long timeBucket, int dayStep) {
    // Step 1: Handle edge cases (e.g. input numbers that are not valid time buckets)
    if (timeBucket < 0 || timeBucket > 9999999999L) {
        throw new IllegalArgumentException("Invalid time bucket: " + timeBucket);
    }

    // Step 2: Extract the date part from the time bucket
    long datePart = timeBucket / 100L;

    // Step 3: Compute the new date part by rounding down to the nearest multiple of dayStep
    long newDatePart = datePart - (datePart % dayStep);

    // Step 4: Combine the new date part with the original time part
    long newTimeBucket = newDatePart * 100L + timeBucket % 100L;

    // Step 5: Return the compressed time bucket
    return newTimeBucket;
}

/**
 * Computes the size of the UTF-8 string starting from the specified {@code index} with the specified {@code length}.
 * @param str The input string.
 * @param index The starting position in the input string.
 * @param len The length of the string to be encoded in UTF-8.
 * @return The size of the UTF-8 encoded string.
 */
public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        size += getUTF8Size(str.charAt(i));
    }
    return size;
}

/**
 * Gets the size of the specified character in UTF-8.
 * @param c The character to get the size of.
 * @return The size of the character in UTF-8, ranging from 1 to 4.
 */
public static int getUTF8Size(char c) {
    int size = 1;
    if (c < 0x80) {
        // Single byte character
        size = 1;
    } else if (c < 0x800) {
        // Two-byte character
        size = 2;
    } else if (c < 0x10000) {
        // Three-byte character
        size = 3;
    } else if (c < 0x110000) {
        // Four-byte character
        size = 4;
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid input arguments");
    }
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= '\u007F') {
            size += 1;
        } else if (c <= '\u07FF') {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            size += 4;
        } else {
            size += 3;
        }
    }
    return size;
}

