public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
  // Check if the input string is null
  if (str == null) {
    throw new IllegalArgumentException("Input string is null");
  }

  // Check if the input index is within the string bounds
  if (index < 0 || index >= str.length()) {
    throw new IndexOutOfBoundsException("Index is outside the bounds of the input string");
  }

  // Check if the input length is valid
  if (len < 0) {
    throw new IllegalArgumentException("Length must be non-negative");
  }

  // Compute the size of the UTF-8 string
  int size = 0;
  for (int i = index; i < len; i++) {
    char c = str.charAt(i);
    if (c <= 0x7F) {
      size += 1;
    } else if (c <= 0x7FF) {
      size += 2;
    } else if (Character.isHighSurrogate(c)) {
      size += 4;
      i++;
    } else {
      size += 3;
    }
  }

  return size;
}

