private Set<V> initVisibleVertices() {
    Set<V> visibleVertices = new HashSet<>();
    for (E edge : graph.edges()) {
        V source = edge.source();
        V destination = edge.destination();
        if (!visibleVertices.contains(source)) {
            visibleVertices.add(source);
        }
        if (!visibleVertices.contains(destination)) {
            visibleVertices.add(destination);
        }
    }
    return visibleVertices;
}

/// <summary>
/// Computes all vertices with positive degree by iterating over the edges.
/// </summary>
/// <returns>A set of vertices with positive degree.</returns>
private HashSet<V> initVisibleVertices()
{
    HashSet<V> visibleVertices = new HashSet<V>();
    foreach (Edge<V> edge in edges)
    {
        visibleVertices.Add(edge.Source);
        visibleVertices.Add(edge.Target);
    }
    return visibleVertices;
}

/**
 * Compute all vertices that have positive degree by iterating over the edges on purpose. This keeps the complexity to $O(m)$ where $m$ is the number of edges.
 * @return set of vertices with positive degree
 */
private Set<V> initVisibleVertices(){
	Set<V> visibleVertices = new HashSet<>();
	for (E edge : graph.edges()) {
		V source = graph.source(edge);
		V target = graph.target(edge);
		if (!visibleVertices.contains(source)) {
			visibleVertices.add(source);
		}
		if (!visibleVertices.contains(target)) {
			visibleVertices.add(target);
		}
	}
	return visibleVertices;
}

