        return this;
    }
    checkByteLength(byteLength);
    checkByteOffsetAndLength(byteOffset, byteLength, byteArrayValue.length);
    for (int i = 0; i < byteLength; i++) {
        putByte(byteArrayValue[byteOffset + i]);
    }
    return this;
}

private void checkByteLength(int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
}

private void checkByteOffsetAndLength(int byteOffset, int byteLength, int byteArrayValueLength) {
    if (byteOffset < 0 || byteOffset > byteArrayValueLength) {
        throw new IllegalArgumentException("byteOffset must be non-negative and less than or equal to the length of the byte array");
    }
    if (byteLength < 0 || byteLength > byteArrayValueLength - byteOffset) {
        throw new IllegalArgumentException("byteLength must be non-negative and less than or equal to the length of the byte array minus the byte offset");
    }
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        // Put null bytes into this byte vector
        return addNullByte(byteLength);
    } else {
        // Copy the specified bytes from the input array into this byte vector
        for (int i = byteOffset; i < byteOffset + byteLength; i++) {
            add(byteArrayValue[i]);
        }
        return this;
    }
}

/**
 * Puts an array of bytes into this byte vector. The byte vector is automatically enlarged if necessary.
 *
 * @param byteArrayValue an array of bytes. May be {@literal null} to put {@code byteLength} nullbytes into this byte vector.
 * @param byteOffset index of the first byte of byteArrayValue that must be copied.
 * @param byteLength number of bytes of byteArrayValue that must be copied.
 * @return this byte vector.
 */
private ByteVector addNullByte(final int byteLength) {
    for (int i = 0; i < byteLength; i++) {
        add(null);
    }
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteArrayValue == null) {
            if (byteOffset < 0 || byteLength < 0) {
                throw new IllegalArgumentException("byteOffset and byteLength must be non-negative");
            }
            if (byteLength > 0) {
                ensureCapacity(byteLength);
                expand(byteLength);
                for (int i = 0; i < byteLength; i++) {
                    data[i] = 0;
                }
            }
            return this;
        }
        if (byteOffset < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset and byteLength are out of bounds");
        }
        ensureCapacity(byteLength);
        expand(byteLength);
        for (int i = 0; i < byteLength; i++) {
            data[i] = byteArrayValue[byteOffset + i];
        }
        return this;
    }

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
  if (byteArrayValue == null) {
    throw new NullPointerException("byteArrayValue cannot be null");
  }

  if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
    throw new IndexOutOfBoundsException("byteOffset out of bounds");
  }

  if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
    throw new IndexOutOfBoundsException("byteLength out of bounds");
  }

  // Automatically enlarge the byte vector if necessary
  if (this.bytes.length < this.length + byteLength) {
    byte[] newBytes = new byte[this.length + byteLength];
    System.arraycopy(this.bytes, 0, newBytes, 0, this.length);
    this.bytes = newBytes;
  }

  // Copy the byte array into the byte vector
  System.arraycopy(byteArrayValue, byteOffset, this.bytes, this.length, byteLength);
  this.length += byteLength;

  return this;
}

