public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || str.length() == 0) {
        return lb;
    }
    if (session == null) {
        throw new IllegalArgumentException("Session cannot be null");
    }
    if (lb == null) {
        lb = allocate(session.getBufferSize());
    }
    int strLength = str.length();
    int utfLength = 0;
    for (int i = 0; i < strLength; i++) {
        utfLength += getUtf8Length(str.charAt(i));
    }
    ensureCapacity(lb, utfLength);
    for (int i = 0; i < strLength; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            lb.writeByte(c);
        } else {
            int utf8Length = getUtf8Length(c);
            writeUtf8(c, lb, utf8Length - 1);
        }
    }
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    try {
        ByteBuffer buffer = lb.getBuffer();
        byte[] bytes = str.toString().getBytes("UTF-8");
        buffer.put(bytes);
        return lb;
    } catch (IllegalArgumentException e) {
        throw new RuntimeException("Invalid input: CharSequence cannot be null", e);
    } catch (UnsupportedEncodingException e) {
        throw new RuntimeException("Failed to encode string as UTF-8", e);
    }
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Handle null input
    if (str == null) {
        throw new IllegalArgumentException("The input string must not be null");
    }

    // Handle empty input
    if (str.length() == 0) {
        return lb;
    }

    // Write the length of the string
    int length = str.length();
    lb.writeInt(length);

    // Write the string itself
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            lb.writeUint8(c);
        } else if (c <= 0x7FF) {
            lb.writeUint8(0xC0 | (c >> 6));
            lb.writeUint8(0x80 | (c & 0x3F));
        } else {
            lb.writeUint8(0xE0 | (c >> 12));
            lb.writeUint8(0x80 | ((c >> 6) & 0x3F));
            lb.writeUint8(0x80 | (c & 0x3F));
        }
    }

    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
  // Step 1: Validate the input
  if (str == null || session == null || lb == null) {
    throw new IllegalArgumentException("Invalid input: CharSequence, WriteSession, and LinkedBuffer must not be null");
  }

  // Step 2: Convert the CharSequence to a UTF-8 encoded byte array
  byte[] bytes = str.toString().getBytes(StandardCharsets.UTF_8);

  // Step 3: Write the bytes to the LinkedBuffer
  lb.write(bytes, 0, bytes.length);

  // Step 4: Return the LinkedBuffer
  return lb;
}

public void removeFromTreeEdgeList(Edge edge) throws EdgeNotInListException {
