    if (!isRemoved) {
        // Get the previous and next edges
        DoublyLinkedList<Edge> previousList = previous.getList();
        DoublyLinkedList<Edge> nextList = next.getList();

        // Remove the edge from the previous and next lists
        previousList.remove(this);
        nextList.remove(this);

        // Set the edge as removed
        isRemoved = true;
    }
}

public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    return substituteVariables(value, props);
}

private static String substituteVariables(String value, Properties props) {
    // Use a regex to find all occurrences of ${variable} in the value.
    Matcher matcher = Pattern.compile("\\$\\{(\\w+)\\}").matcher(value);
    while (matcher.find()) {
        // Get the variable name from the regex match.
        String variable = matcher.group(1);
        // Get the value of the variable from the properties.
        String varValue = props.getProperty(variable);
        // Replace the variable with its value in the original value string.
        value = value.replace("${" + variable + "}", varValue);
    }
    return value;
}

