  return substituteVariables(value, props);
}

/**
 * Perform variable substitution on the given <code>value</code> using the given <code>props</code>.
 */
public static String substituteVariables(String value, Properties props) throws UnsupportedEncodingException {
  Pattern pattern = Pattern.compile("\\$\\{(.+?)\\}");
  Matcher matcher = pattern.matcher(value);
  StringBuffer buffer = new StringBuffer();
  while (matcher.find()) {
    String variable = matcher.group(1);
    String replacement = props.getProperty(variable);
    if (replacement == null) {
      replacement = "";
    }
    matcher.appendReplacement(buffer, replacement);
  }
  matcher.appendTail(buffer);
  return buffer.toString();
}

