/**
 * Return the next  {@link java.io.File} object or {@code null} if no more files are available.
 */
public InputStream next() throws IOException {
    // Step 1: Check if there are any more files to be processed
    if (this.files.isEmpty()) {
        return null;
    }

    // Step 2: Get the next file from the list of files
    File file = this.files.get(0);

    // Step 3: Check if the file exists and is readable
    if (!file.exists() || !file.canRead()) {
        throw new IOException("File not found or not readable: " + file.getPath());
    }

    // Step 4: Create a new input stream for the file
    InputStream inputStream = new FileInputStream(file);

    // Step 5: Remove the file from the list of files to be processed
    this.files.remove(0);

    // Step 6: Return the input stream
    return inputStream;
}

