/**
   * Pops as many abstract types from the output frame stack as described by the given descriptor.
   * @param descriptor a type or method descriptor (in which case its argument types are popped).
   */
  private void pop(final String descriptor) {
      // Check if the descriptor is a type descriptor
      if (descriptor.contains(".")) {
          // Pop the type from the stack
          Type type = Type.getType(descriptor);
          stack.pop(type, false);
      } else {
          // Pop the method descriptor
          MethodDescriptor methodDescriptor = MethodDescriptor.parse(descriptor);
          stack.pop(methodDescriptor.getReturnType(), false);
          // Pop the argument types
          for (Type argumentType : methodDescriptor.getArgumentTypes()) {
              stack.pop(argumentType, false);
          }
      }
  }

@Override
public void pop(String descriptor) {
    try {
        int numTypes = argumentTypes(descriptor).length;
        while (numTypes > 0) {
            Object obj = frame.pop();
            if (!(obj instanceof AbstractType)) {
                throw new IllegalStateException("Attempted to pop a non-abstract type from the stack");
            }
            AbstractType type = (AbstractType) obj;
            if (!type.isConcrete()) {
                throw new IllegalStateException("Attempted to pop an abstract type that is not concrete");
            }
            numTypes--;
        }
    } catch (RuntimeException e) {
        throw new IllegalStateException("Failed to pop abstract types from the stack", e);
    }
}

public void pop(final String descriptor) {
  if (descriptor == null) {
    throw new IllegalArgumentException("Descriptor cannot be null");
  }
  if (descriptor.isEmpty()) {
    return;
  }
  int index = descriptor.lastIndexOf(')');
  if (index < 0) {
    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
  }
  int outputFrameSize = index + 1;
  if (outputFrameSize > MAX_ARRAY_SIZE) {
    throw new IllegalArgumentException("Output frame size exceeds maximum size");
  }
  Object[] outputFrame = new Object[outputFrameSize];
  for (int i = 0; i < outputFrameSize; i++) {
    outputFrame[i] = pop();
  }
  push(outputFrame);
}

