 * @param j the index of the second element
 */
public static final <V>void swap(V[] arr,int i,int j){
	if(arr == null){
		throw new NullPointerException("The array cannot be null");
	}
	if(i < 0 || i >= arr.length){
		throw new IndexOutOfBoundsException("The first index is out of bounds");
	}
	if(j < 0 || j >= arr.length){
		throw new IndexOutOfBoundsException("The second index is out of bounds");
	}

	V temp = arr[i];
	arr[i] = arr[j];
	arr[j] = temp;
}

