  if (desiredCapacity < 0) {
    throw new IllegalArgumentException("Desired capacity must be a positive integer.");
  }

  // Step 2: Find the next prime number greater than or equal to the desired capacity
  double approximateCapacity = desiredCapacity * 1.11; // 11% higher than desired capacity
  while (!isPrime(approximateCapacity)) {
    approximateCapacity += 1;
  }

