protected Object filter(Object msg) {
    // Handle potential invalid inputs
    if (msg == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (!(msg instanceof BroadcastFilter)) {
        throw new IllegalArgumentException("Message must be an instance of BroadcastFilter");
    }

    // Call the filter() method of the BroadcastFilter
    return ((BroadcastFilter) msg).filter();
}

protected Object filter(Object msg) {
    // Check if the message is null
    if (msg == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }

    // Check if the message is a String
    if (!(msg instanceof String)) {
        throw new IllegalArgumentException("Message must be a String");
    }

    // Invoke the BroadcastFilter
    Object result = BroadcastFilter.filter(msg);

    // Check if the result is null
    if (result == null) {
        throw new RuntimeException("BroadcastFilter returned null");
    }

    // Check if the result is a String
    if (!(result instanceof String)) {
        throw new RuntimeException("BroadcastFilter returned a non-String value");
    }

    return result;
}

protected Object filter(Object msg) {
    if (!(msg instanceof Message)) {
        throw new IllegalArgumentException("msg must be an instance of Message");
    }
    Message message = (Message) msg;
    if (!message.isFiltered()) {
        return null;
    }
    BroadcastFilter filter = getBroadcastFilter();
    if (filter == null) {
        throw new IllegalStateException("No BroadcastFilter registered");
    }
    return filter.apply(message);
}

protected Object filter(Object msg) {
    if (msg == null) {
        return msg;
    }

    try {
        BroadcastFilter filter = new BroadcastFilter();
        Object filteredMsg = filter.filter(msg);
        return filteredMsg;
    } catch (Exception e) {
        // Handle exception here
        throw new RuntimeException(e);
    }
}

