public final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
	// Read the length of the string in bytes
	int stringLength = classFileBuffer.getShort(constantPoolEntryIndex + 2);

	// Read the bytes of the string
	byte[] stringBytes = new byte[stringLength];
	classFileBuffer.position(constantPoolEntryIndex + 4);
	classFileBuffer.get(stringBytes);

	// Convert the bytes to a string using the UTF-8 encoding
	String string = new String(stringBytes, StandardCharsets.UTF_8);

	// Copy the string into the output buffer
	System.arraycopy(string, 0, charBuffer, 0, stringLength);

	return string;
}

private static char decodeHexNibble(final char c) {
    if (!Character.isDigit(c) && !(c >= 'a' && c <= 'f') && !(c >= 'A' && c <= 'F')) {
