private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // initialize circulator to start node
    OuterFaceCirculator circ = new OuterFaceCirculator(start);
    // move circulator to the next node in the direction specified
    circ.move(dir);

    // check if the current node satisfies the predicate
    if (predicate.test(circ.getNode())) {
        // return circulator to the current node
        return circ;
    } else {
        // continue moving the circulator until we reach the stop node
        while (circ.getNode() != stop) {
            circ.move(dir);
            // check if the current node satisfies the predicate
            if (predicate.test(circ.getNode())) {
                // return circulator to the current node
                return circ;
            }
        }
        // we have reached the stop node, return a circulator to it
        return new OuterFaceCirculator(stop);
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (circulator.hasNext()) {
        Node current = circulator.next();
        if (predicate.test(current)) {
            return circulator;
        }
        if (current == stop) {
            return new OuterFaceCirculator(stop, -dir);
        }
    }
    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Check if the predicate is valid
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }

    // Check if the start and stop nodes are not null
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }

    // Check if the direction is valid
    if (dir != 0 && dir != 1) {
        throw new IllegalArgumentException("Invalid direction");
    }

    // Initialize the circulator
    OuterFaceCirculator circulator = new OuterFaceCirculator(this, start, dir);

    // Iterate through the nodes on the outer face and find the first node that satisfies the predicate
    while (circulator.hasNext()) {
        Node node = circulator.next();
        if (predicate.test(node)) {
            return circulator;
        }
    }

    // If no node satisfies the predicate, return the stop node
    return new OuterFaceCirculator(this, stop, dir);
}

