public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
  // Initialize variables
  int currentIndex = byteOffset;
  int bytesCopied = 0;

  // Handle null byte array
  if (byteArrayValue == null) {
    // Calculate number of null bytes to copy
    int nullBytesToCopy = Math.min(byteLength, this.length - this.offset);

    // Copy null bytes to this byte vector
    while (nullBytesToCopy > 0) {
      this.data[this.offset++] = 0;
      nullBytesToCopy--;
      bytesCopied++;
    }

    // Return this byte vector
    return this;
  }

  // Handle valid byte array
  int availableBytes = this.length - this.offset;
  int bytesToCopy = Math.min(byteLength, availableBytes);

  // Copy bytes to this byte vector
  while (bytesToCopy > 0) {
    this.data[this.offset++] = byteArrayValue[currentIndex++];
    bytesToCopy--;
    bytesCopied++;
  }

  // Check if all bytes were copied
  if (bytesCopied < byteLength) {
    // Throw insufficient space exception
    throw new IllegalArgumentException("Insufficient space to put all bytes");
  }

  // Return this byte vector
  return this;
}

