 *
 * @param v the vertex
 * @return the sum of the weights entering a vertex
 */
public double vertexWeight(Set<V> v) {
	// Initialize the weight sum
	double weightSum = 0.0;

	// Iterate over the edges entering the vertex
	for (Edge<V> edge : v.getEdges()) {
		// Get the weight of the current edge
		double weight = edge.getWeight();

		// Add the weight to the sum
		weightSum += weight;
	}

	// Return the sum of the weights entering the vertex
	return weightSum;
}

