public static void selectRow(int row, JTable table, JScrollPane pane) {
    /*
     * The following code blocks are used to ensure that the given row is visible in the scroll pane.
     * The scrolling is done by calling `scrollRectToVisible` on the scroll pane, which takes a `Rectangle`
     * object as its parameter. The rectangle to be scrolled should be calculated such that it covers the 
     * entire row of the table.
     */
    int rowHeight = table.getRowHeight();
    int rowY = row * rowHeight;
    int tableWidth = table.getWidth();
    Rectangle rowRect = new Rectangle(0, rowY, tableWidth, rowHeight);
    pane.scrollRectToVisible(rowRect);

    /*
     * Now that the row is visible, we need to select it in the table.
     * This is done by calling `setSelectionInterval` on the table, which takes two integers as its 
     * parameters: the first is the first row to be selected, and the second is the last row to be selected.
     * In this case, we want to select only the given row, so we pass the same value for both parameters.
     */
    table.setSelectionInterval(row, row);
}

