    }
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Name start index out of bounds");
    }
    String name = buf.toString();
    int index = nameStart;
    while (index < buf.length() && !Character.isWhitespace(name.charAt(index))) {
        index++;
    }
    if (index == nameStart) {
        throw new IllegalArgumentException("Invalid name at index " + nameStart);
    }
    buf.replace(nameStart, index, name.substring(nameStart, index));
