public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IndexOutOfBoundsException("Name starting index is out of bounds");
    }
    // Check if the buffer is already empty
    if (buf.length() == 0) {
        return;
    }
    int nameLength = buf.length() - nameStart;
    // Compute the expected abbreviation length
    int expectedAbbreviationLength = (int) Math.ceil((double) nameLength / 2.0);
    // Check if the abbreviation exceeds the buffer capacity
    if (expectedAbbreviationLength > buf.capacity()) {
        throw new RuntimeException("Abbreviation exceeds buffer capacity");
    }
    // Set the initial indices
    int nameIndex = nameStart;
    int abbreviationIndex = 0;
    // Loop through the name and compute the abbreviation
    while (nameIndex < nameStart + nameLength) {
        char currentChar = buf.charAt(nameIndex);
        if (!Character.isWhitespace(currentChar)) {
            buf.setCharAt(abbreviationIndex, currentChar);
            abbreviationIndex++;
        }
        nameIndex++;
    }
    // Set the abbreviation length
    int actualAbbreviationLength = buf.length() - nameStart;
    if (actualAbbreviationLength != expectedAbbreviationLength) {
        throw new RuntimeException("Actual abbreviation length does not match expected abbreviation length");
    }
}

