private List<Integer> computeUpperBounds(List<K> keys) {
        Preconditions.checkNotNull(keys, "keys can't be null");

        List<Integer> upperBounds = new ArrayList<>();
        for (K key : keys) {
            int step = key % 2 == 0 ? 1 : -1;
            int bound = key / 2;
            for (int i = 0; i < bound; i++) {
                int upperBound = bound + step * i;
                if (upperBound != 0 && upperBound % 2 == 1) {
                    upperBounds.add(upperBound);
                }
            }
        }
        return upperBounds;
    }

private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null || keys.isEmpty()) {
        return Collections.emptyList();
    }
    List<Integer> upperBounds = new ArrayList<>();
    for (K key : keys) {
        int upperBound = 0;
        for (K k : keys) {
            if (k.compareTo(key) > 0) {
                upperBound = Math.max(upperBound, k);
            }
        }
        upperBounds.add(upperBound);
    }
    return upperBounds;

}

This method computes the minimum lower bound for every key in the list using a divide and conquer approach. The method is guaranteed to return a list of integers, where each integer represents the lower bound for the corresponding key.

