@Override
public List<Integer> computeUpperBounds(List<K> keys) {
    if (keys.isEmpty()) {
        return Collections.emptyList();
    } else {
        int n = keys.size();
        int mid = n / 2;
        List<Integer> leftBounds = computeUpperBounds(keys.subList(0, mid));
        List<Integer> rightBounds = computeUpperBounds(keys.subList(mid, n));
        return mergeBounds(leftBounds, rightBounds, 0, n - 1);
    }
}

private List<Integer> mergeBounds(List<Integer> leftBounds, List<Integer> rightBounds,
                                 int start, int end) {
    List<Integer> result = new ArrayList<>();
    int left = start;
    int right = end - 1;
    while (left < end && right >= 0) {
        if (leftBounds.get(left) < rightBounds.get(right)) {
            result.add(leftBounds.get(left));
            left++;
        } else {
            result.add(rightBounds.get(right));
            right--;
        }
    }
    if (left < end) {
        result.addAll(leftBounds.subList(left, end));
    } else if (right >= 0) {
        result.addAll(rightBounds.subList(0, right + 1));
    }
    return result;
}

public static String encodeTemplateNames(String s) {
    // Initialize a new string builder with the input string
    StringBuilder sb = new StringBuilder(s);

    // Set up a pattern to capture template parameter names
    Pattern pattern = Pattern.compile("[{][^}]+[}]");

    // Match the pattern against the input string
    Matcher matcher = pattern.matcher(s);

    // While there are still matches to be found
    while (matcher.find()) {
        // Get the matched group
        String group = matcher.group();

        // For each character in the matched group that is not a letter or digit, percent-encode it
        for (int i = 0; i < group.length(); i++) {
            char c = group.charAt(i);
            if (!Character.isLetterOrDigit(c)) {
                sb.setCharAt(i, '%' + String.format("%02x", (int) c));
            }
        }
    }

    // Return the encoded string
    return sb.toString();
}

