  // Step 1: Check if expiredThreshold is positive
  if (expiredThreshold <= 0) {
    throw new IllegalArgumentException("expiredThreshold must be positive.");
  }

  // Step 2: Check if timestamp is greater than or equal to last updated time + expiredThreshold
  if (timestamp >= lastUpdatedTime + expiredThreshold) {
    return true;
  }

  // Step 3: If not expired, return false
  return false;
}

